-- =============================================================================
-- STUDENT INTERNSHIP AND ATTACHMENT MANAGEMENT SYSTEM
-- Langata Technical and Vocational College
-- PostgreSQL schema - database: student_internship_management
--
-- GENERATED from the Django models (Backend/apps/*/models.py) by
-- Database/generate_schema.py. Do not edit by hand: the Django migrations are the
-- source of truth. The normal way to create the tables is
--
--     cd Backend && python manage.py migrate
--
-- This file is a reference copy (and can bootstrap an empty database with
-- psql -d student_internship_management -f schema.sql, but then Django must be
-- told the migrations are applied:  python manage.py migrate --fake).
--
-- The 17 tables of the design document (Chapter 7) are:
--   users, students, academic_supervisors, industrial_supervisors, departments,
--   organizations, placements, supervisor_assignments, logbooks, logbook_reviews,
--   supervision_visits, final_reports, assessments, announcements, notifications,
--   attendance, audit_logs
-- plus attachment_periods and system_settings, and the tables Django and the JWT
-- blacklist need (auth_*, django_*, token_blacklist_*, users_groups,
-- users_user_permissions).
-- =============================================================================

BEGIN;

CREATE TABLE "users" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "email" varchar(254) NOT NULL UNIQUE, "role" varchar(20) NOT NULL, "is_active" boolean NOT NULL, "is_staff" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);
CREATE TABLE "users_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "users_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "departments" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "department_name" varchar(150) NOT NULL UNIQUE, "department_code" varchar(20) NOT NULL UNIQUE, "description" text NOT NULL);
CREATE TABLE "audit_logs" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NULL, "action" varchar(60) NOT NULL, "description" text NOT NULL, "timestamp" timestamp with time zone NOT NULL, "ip_address" inet NULL);
CREATE TABLE "system_settings" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "institution_name" varchar(200) NOT NULL, "allow_student_registration" boolean NOT NULL, "required_logbook_weeks" smallint NOT NULL CHECK ("required_logbook_weeks" >= 0), "updated_at" timestamp with time zone NOT NULL, "updated_by_id" bigint NULL);
CREATE TABLE "students" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL UNIQUE, "registration_number" varchar(40) NOT NULL UNIQUE, "first_name" varchar(80) NOT NULL, "last_name" varchar(80) NOT NULL, "phone_number" varchar(30) NOT NULL, "department_id" bigint NOT NULL, "academic_year" varchar(10) NOT NULL);
CREATE TABLE "academic_supervisors" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL UNIQUE, "staff_number" varchar(40) NOT NULL UNIQUE, "first_name" varchar(80) NOT NULL, "last_name" varchar(80) NOT NULL, "phone_number" varchar(30) NOT NULL, "department_id" bigint NOT NULL);
CREATE TABLE "industrial_supervisors" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL UNIQUE, "organization_id" bigint NOT NULL, "employee_number" varchar(40) NOT NULL, "first_name" varchar(80) NOT NULL, "last_name" varchar(80) NOT NULL, "phone_number" varchar(30) NOT NULL, "job_title" varchar(120) NOT NULL);
CREATE TABLE "supervisor_assignments" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "placement_id" bigint NOT NULL, "student_id" bigint NOT NULL, "academic_supervisor_id" bigint NOT NULL, "industrial_supervisor_id" bigint NOT NULL, "assigned_date" timestamp with time zone NOT NULL, "assignment_status" varchar(10) NOT NULL, "assigned_by_id" bigint NULL);
CREATE TABLE "organizations" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "organization_name" varchar(200) NOT NULL, "address" varchar(255) NOT NULL, "county" varchar(100) NOT NULL, "contact_person" varchar(150) NOT NULL, "phone_number" varchar(30) NOT NULL, "email" varchar(254) NOT NULL, "industry_category" varchar(120) NOT NULL, "status" varchar(10) NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "attachment_periods" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(120) NOT NULL UNIQUE, "start_date" date NOT NULL, "end_date" date NOT NULL, "application_deadline" date NOT NULL, "report_deadline" date NOT NULL, "is_active" boolean NOT NULL, CONSTRAINT "period_end_after_start" CHECK ("end_date" > ("start_date")));
CREATE TABLE "placements" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "organization_id" bigint NOT NULL, "attachment_period_id" bigint NULL, "start_date" date NOT NULL, "end_date" date NOT NULL, "application_date" timestamp with time zone NOT NULL, "application_status" varchar(10) NOT NULL, "attachment_status" varchar(12) NOT NULL, "supporting_document" varchar(100) NOT NULL, "withdrawal_reason" text NOT NULL, "approval_comments" text NOT NULL, "reviewed_by_id" bigint NULL, "reviewed_at" timestamp with time zone NULL, "updated_at" timestamp with time zone NOT NULL, CONSTRAINT "placement_end_after_start" CHECK ("end_date" > ("start_date")));
CREATE TABLE "logbooks" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "placement_id" bigint NOT NULL, "week_number" smallint NOT NULL CHECK ("week_number" >= 0), "start_date" date NOT NULL, "end_date" date NOT NULL, "activities" text NOT NULL, "skills_acquired" text NOT NULL, "challenges" text NOT NULL, "solutions" text NOT NULL, "attachment" varchar(100) NOT NULL, "submission_date" timestamp with time zone NOT NULL, "status" varchar(12) NOT NULL, "updated_at" timestamp with time zone NOT NULL, CONSTRAINT "one_logbook_per_week" UNIQUE ("placement_id", "week_number"), CONSTRAINT "logbook_end_after_start" CHECK ("end_date" >= ("start_date")));
CREATE TABLE "logbook_reviews" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "logbook_id" bigint NOT NULL, "supervisor_id" bigint NOT NULL, "supervisor_role" varchar(12) NOT NULL, "review_status" varchar(10) NOT NULL, "comments" text NOT NULL, "review_date" timestamp with time zone NULL, CONSTRAINT "one_review_per_supervisor_role" UNIQUE ("logbook_id", "supervisor_role"));
CREATE TABLE "attendance" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "attendance_date" date NOT NULL, "attendance_status" varchar(10) NOT NULL, "remarks" varchar(255) NOT NULL, "recorded_by_id" bigint NULL, "created_at" timestamp with time zone NOT NULL, CONSTRAINT "one_attendance_per_day" UNIQUE ("student_id", "attendance_date"));
CREATE TABLE "supervision_visits" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "academic_supervisor_id" bigint NOT NULL, "organization_id" bigint NULL, "visit_date" timestamp with time zone NOT NULL, "visit_type" varchar(10) NOT NULL, "meeting_link" varchar(200) NOT NULL, "objectives" text NOT NULL, "observations" text NOT NULL, "recommendations" text NOT NULL, "visit_status" varchar(12) NOT NULL, "created_by_id" bigint NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "assessments" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "placement_id" bigint NOT NULL, "supervisor_id" bigint NOT NULL, "supervisor_role" varchar(12) NOT NULL, "assessment_type" varchar(10) NOT NULL, "assessment_criteria" jsonb NOT NULL, "marks" numeric(5, 2) NOT NULL, "comments" text NOT NULL, "recommendations" text NOT NULL, "evaluation_form" varchar(100) NOT NULL, "assessment_date" date NOT NULL, "assessment_status" varchar(12) NOT NULL, "released_by_id" bigint NULL, "released_at" timestamp with time zone NULL, "updated_at" timestamp with time zone NOT NULL, CONSTRAINT "one_assessment_per_type" UNIQUE ("placement_id", "assessment_type"));
CREATE TABLE "final_reports" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "student_id" bigint NOT NULL, "placement_id" bigint NOT NULL, "version" smallint NOT NULL CHECK ("version" >= 0), "title" varchar(200) NOT NULL, "report_file" varchar(100) NOT NULL, "original_filename" varchar(255) NOT NULL, "submission_date" timestamp with time zone NOT NULL, "review_status" varchar(12) NOT NULL, "feedback" text NOT NULL, "reviewed_by_id" bigint NULL, "review_date" timestamp with time zone NULL, CONSTRAINT "unique_report_version" UNIQUE ("placement_id", "version"));
CREATE TABLE "announcements" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "administrator_id" bigint NULL, "title" varchar(200) NOT NULL, "message" text NOT NULL, "target_audience" varchar(12) NOT NULL, "publication_date" timestamp with time zone NOT NULL, "expiry_date" date NULL);
CREATE TABLE "notifications" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "title" varchar(200) NOT NULL, "message" text NOT NULL, "notification_type" varchar(15) NOT NULL, "link" varchar(255) NOT NULL, "is_read" boolean NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL, "content_type_id" integer NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE TABLE "token_blacklist_outstandingtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NULL, "jti" varchar(255) NOT NULL UNIQUE, "token" text NOT NULL, "created_at" timestamp with time zone NULL, "expires_at" timestamp with time zone NOT NULL);
CREATE TABLE "token_blacklist_blacklistedtoken" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token_id" bigint NOT NULL UNIQUE, "blacklisted_at" timestamp with time zone NOT NULL);
